// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callerSeed) public {
        // Bound callerSeed to create a variety of addresses
        address caller = address(uint160(bound(callerSeed, 1, type(uint160).max)));
        vm.deal(caller, 10 ether);
        uint256 pastBefore = c.pastBlockTime();
        vm.prank(caller);
        // Call fallback by sending ether with data
        (bool success, ) = address(c).call{value: 10 ether}("");
        uint256 pastAfter = c.pastBlockTime();
        // The reference contract updates pastBlockTime to block.timestamp, so it increases.
        // The buggy contract does not update, so pastBlockTime stays the same.
        // Rule: if the call succeeds, pastBlockTime must increase strictly.
        assertTrue(!success || pastAfter > pastBefore);
    }
}

